const body = $json.body ?? $json;
const typFehler = ['position','standort','anforderungen','zusatz','test_id'].filter(k => body[k] !== undefined && body[k] !== null && typeof body[k] !== 'string');
if (typFehler.length) {
  return [{json: {test_id: typeof body.test_id === 'string' ? body.test_id : 'MANUELL', fehler: 'Falscher Datentyp: Felder müssen Text (String) sein', detail: 'Betroffene Felder: ' + typFehler.join(', '), status:'EINGABE_UNGUELTIG', http_status:400}}];
}
const position = String(body.position ?? '').trim();
const standort = String(body.standort ?? '').trim();
const anforderungen = String(body.anforderungen ?? '').trim();
const zusatz = String(body.zusatz ?? '').trim();
const test_id = String(body.test_id ?? 'MANUELL').trim();
if (!position || !anforderungen) {
  return [{json: {test_id, position, standort, fehler: 'Position und Anforderungen sind Pflichtfelder', status:'EINGABE_UNVOLLSTAENDIG', http_status:400}}];
}
return [{json: {test_id, position, standort, anforderungen, zusatz, status:'VALIDIERT'}}];

let test_id = 'MANUELL';
try { test_id = $('Eingabe validieren').first().json.test_id ?? 'MANUELL'; } catch (e) {}
const fail = (grund, detail) => [{json: {
  status: 'KI_FEHLER',
  http_status: 502,
  test_id,
  fehler: grund,
  detail: String(detail ?? '').slice(0, 300),
  hinweis: 'Die KI-Analyse konnte nicht abgeschlossen werden. Bitte später erneut versuchen oder die Anfrage manuell prüfen.'
}}];

const r = $json;
if (r.error) {
  const msg = typeof r.error === 'string' ? r.error : (r.error.message ?? JSON.stringify(r.error));
  return fail('OpenAI-Aufruf fehlgeschlagen', msg);
}
let a = r.output?.[0]?.content?.[0]?.text;
if (typeof a === 'string') {
  try { a = JSON.parse(a); } catch (e) { return fail('KI-Antwort ist kein gültiges JSON', e.message); }
}
if (!a || typeof a !== 'object' || Array.isArray(a)) {
  return fail('Keine auswertbare KI-Antwort', 'Antwort leer oder falsches Format');
}
const required = ['position','standort','muss','wunsch','schwierigkeit','begruendung','verwandte_berufe','suchbegriffe','strategie','offene_fragen','warnungen'];
const missing = required.filter(k => !(k in a));
if (missing.length) return fail('KI-Antwort unvollständig', 'Fehlende Felder: ' + missing.join(', '));
const stringFields = ['position','standort','schwierigkeit','begruendung','strategie'];
const listFields = ['muss','wunsch','verwandte_berufe','suchbegriffe','offene_fragen','warnungen'];
for (const k of ['widersprueche','unsicherheiten']) { if (!(k in a) || a[k] === undefined) a[k] = []; listFields.push(k); }
for (const k of stringFields) {
  if (typeof a[k] !== 'string') return fail('KI-Antwort ungültig', 'Falscher Feldtyp: ' + k + ' muss String sein');
}
for (const k of listFields) {
  if (!Array.isArray(a[k])) return fail('KI-Antwort ungültig', 'Falscher Feldtyp: ' + k + ' muss Array sein');
  const bad = a[k].findIndex(x => typeof x !== 'string');
  if (bad !== -1) return fail('KI-Antwort ungültig', 'Falscher Feldtyp: ' + k + '[' + bad + '] muss String sein');
}
const rueckfrage = a.suchbegriffe.length < 3;
if (rueckfrage && a.warnungen.length === 0 && a.unsicherheiten.length === 0 && a.offene_fragen.length === 0) return fail('KI-Antwort ungültig', 'Weniger als drei Suchbegriffe ohne Warnung oder Rückfrage');
if (a.widersprueche.length > 0 && a.warnungen.length === 0) return fail('KI-Antwort ungültig', 'Widersprüche ohne Warnung');
return [{json: {status: 'PRUEFUNG_ERFOLGREICH', test_id, rueckfrage_noetig: rueckfrage, analyse: a, hinweis: rueckfrage ? 'Anfrage zu ungenau: Weniger als drei Suchbegriffe, bitte Warnungen und offene Rückfragen klären. KI-Entwurf: menschliche Qualitätsprüfung erforderlich' : 'KI-Entwurf: menschliche Qualitätsprüfung erforderlich'}}];
